package com.kilombino.pyblockwatch

import com.kilombino.pyblockwatch.crypto.TxParse
import org.junit.Assert.assertEquals
import org.junit.Test

/** Virtual size (for CPFP's package fee), against what Bitcoin Knots reports for real transactions. */
class TxVsizeTest {
    @Test fun matchesTheNode() {
        assertEquals(141, TxParse.vsize(""))   // P2WPKH, 1 in 2 out (the PSBT test send)
        assertEquals(212, TxParse.vsize(""))   // Taproot channel funding
        assertEquals(154, TxParse.vsize(""))
    }
}
